scripts.gcd_script:
def solve(inputs: dict) -> float:
    p_minus_1, p_minus_2 = 1, inputs['A']
    for a in inputs['TERMS'][1]:
        p_minus_1, p_minus_2 = p_minus_2, a * p_minus_2 + p_minus_1
    return p_minus_2

